# Reload and check for demos
def load_all_demos():
    G = {}

    # Check session-artifacts
    all_entries = []
    for root, dirs, files in os.walk(session_artifacts_dir):
        for f in files:
            if f.endswith('.jsonl'):
                full_path = os.path.join(root, f)
                print(f"Checking: {full_path}")
                with open(full_path, 'r') as fp:
                    for line in fp:
                        if line.strip():
                            all_entries.append(json.loads(line.strip()))

    # Check workspace sessions
    for f in os.listdir(session_dir):
        if f.endswith('.jsonl'):
            full_path = os.path.join(session_dir, f)
            with open(full_path, 'r') as fp:
                for line in fp:
                    if line.strip():
                        all_entries.append(json.loads(line.strip()))

    demos = []
    for entry in all_entries:
        if 'action' in entry:
            action = entry['action']
            if action == 'request_demos' and 'demos' in entry:
                demos.extend(entry['demos'])
            elif action == 'demo' and 'input' in entry:
                demos.append(entry)

    return demos, all_entries

