def transform(grid):
    result = [row[:] for row in grid]

    line_rows = [r for r in range(len(grid)) if all(grid[r][c] == 2 for c in range(len(grid[0])))]

    for r in range(len(grid) - 2):
        for c in range(len(grid[0]) - 2):
            # Check for 3x3 donut with border of 3s
            is_donut = True
            if grid[r][c] != 3 or grid[r][c+1] != 3 or grid[r][c+2] != 3:
                is_donut = False
            if grid[r+1][c] != 3 or grid[r+1][c+2] != 3:
                is_donut = False
            if grid[r+2][c] != 3 or grid[r+2][c+1] != 3 or grid[r+2][c+2] != 3:
                is_donut = False

            if is_donut:
                center_r, center_c = r + 1, c + 1

                # For each line within 5 rows below donut center
                for line_r in line_rows:
                    if line_r > center_r and line_r - center_r <= 5:
                        new_center_r = line_r - 1
                        new_center_c = center_c

                        # Row offset from start of pattern (which starts at new_center_r - 2)
                        row_off = lambda r: r - (new_center_r - 2)

                        def get_fill_cols(roff):
                            if roff < 0 or roff > 6:
                                return []
                            elif roff in [0, 1]:
                                return [new_center_c]
                            elif roff in [2, 3, 4]:
                                return [new_center_c - 1, new_center_c, new_center_c + 1]
                            elif roff in [5, 6]:
                                return [new_center_c]
                            return []

                        for r_fill in range(max(0, new_center_r - 3), min(len(result), new_center_r + 5)):
                            roff = row_off(r_fill)
                            fill_cols = get_fill_cols(roff)

                            for fc in fill_cols:
                                if 0 <= fc < len(result[0]):
                                    # Don't overwrite 3s (preserve donut)
                                    if grid[r_fill][fc] == 3:
                                        continue
                                    # For line row (r_fill == line_r):
                                    #   - Skip center column (it's 2, should stay 2)
                                    #   - Fill side columns even if they are 2s
                                    # For other rows: skip 2s
                                    if r_fill == line_r:
                                        if fc == new_center_c:
                                            continue  # Skip center
                                        result[r_fill][fc] = 1
                                    elif grid[r_fill][fc] == 2:
                                        continue  # Skip 2s in non-line rows
                                    result[r_fill][fc] = 1

